{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "ACCEPT",
      "evidence": "20% for general warranties is within the commonly seen range. On its own it is not the main fight."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "tipping basket at about 0.5%, de minimis at about AUD 10–15k with aggregation of related claims."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "ACCEPT",
      "evidence": "18 months for general warranties is acceptable."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title and capacity at 100% cap with statutory limitation period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Fraud, dishonesty and wilful concealment should be uncapped."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "No general data-room or public-register disclosure, and no disclosure against fundamental warranties, tax or indemnities."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "pro-sandbagging, or at most actual knowledge of named individuals. Delete \"discoverable\" and the attribution of advisers' knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "a Buyer-only-waivable CP requiring unconditional (or Buyer-acceptable) consent that satisfies clause 11.3"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "paid out from the price at Completion, with a payout letter, deeds of release and PPSR discharges as Completion deliverables."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "AUD 420k plus all on-costs treated as Transaction Costs, deducted from the price, with a specific indemnity."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "payment and confirmatory assignment at Completion, or a retention plus a full IP-loss indemnity outside the cap."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "urgent information request, a pre-Completion assessment and notification covenant, and an uncapped or separately capped specific indemnity outside thresholds."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "information request; Leakage or Debt treatment if outside ordinary course or related-party; tighter interim covenants."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject the sweep that \"any limitation applying to Claims applies to all Claims unless expressly stated otherwise.\""
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "independent verification (ASIC, PPSR, constitution, minutes) before signing."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "IP ownership warranties should at least be excluded from general disclosure and have a longer survival period."
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "20% for general warranties is within the commonly seen range. On its own it is not the main fight.",
  "names_manipulation": false
}

